import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import Input from './Input';

describe('Input', () => {
  describe('Input', () => {
    test('should render input with label', () => {
      render(<Input label="Name" />);
      expect(screen.getByText('Name')).toBeInTheDocument();
    });

    test('should call callback function with the actual value when something is typed', () => {
      const handleChange = jest.fn();
      render(<Input label="Name" onChange={handleChange} data-testid="input-test" />);
      const input = screen.getByTestId('input-test');
      fireEvent.change(input, { target: { value: 'abc' } });
      expect(handleChange).toHaveBeenCalledTimes(1);
      expect(input.value).toBe('abc');
    });

    test('should not call callback function with the actual value when something is typed but it is not passed a onChange argument', () => {
      render(<Input label="Name" data-testid="input-test" />);
      const input = screen.getByTestId('input-test');
      fireEvent.change(input, { target: { value: 'abc' } });
      expect(screen.getByText('Name')).toBeInTheDocument();
    });

    test('should render input with hint text', () => {
      render(<Input label="Label" hint="Hint Text" />);
      expect(screen.getByText('Hint Text')).toBeInTheDocument();
    });

    test('should render disabled input', () => {
      render(<Input label="Label" disabled />);
      expect(screen.getByText('Label')).toBeInTheDocument();
    });

    test('should render input without label', () => {
      render(<Input placeholder="placeholder" />);
      expect(screen.queryByText('placeholder')).not.toBeInTheDocument();
    });

    test('should render input with error text', () => {
      render(<Input label={false} errorText="Error Text" hasError />);
      expect(screen.getByText('Error Text')).toBeInTheDocument();
    });

    test('should render input with error text even when disabled', () => {
      render(
        <Input label="Label" errorText="Error Text" hasError disabled data-testid="input-test" />
      );
      const input = screen.getByTestId('input-test');
      expect(screen.getByText('Error Text')).toBeInTheDocument();
      expect(input.disabled).toBe(true);
    });

    test('should render input with legend text', () => {
      render(<Input label={false} legend="Legend" />);
      expect(screen.getByText('Legend')).toBeInTheDocument();
    });

    test('should render input with default value', () => {
      render(<Input defaultValue="Default Value" data-testid="input-test" />);
      const input = screen.getByTestId('input-test');
      expect(input.value).toBe('Default Value');
    });

    test('should render when controlled', () => {
      let mockValue = '';
      const mockOnChange = jest.fn();
      mockOnChange.mockImplementation((event) => {
        mockValue = event.target.value;
      });

      const { rerender } = render(
        <Input value={mockValue} onChange={mockOnChange} data-testid="input-test" />
      );
      const input = screen.getByTestId('input-test');
      fireEvent.change(input, { target: { value: 'abc' } });
      expect(mockOnChange).toHaveBeenCalledTimes(1);
      rerender(<Input value={mockValue} onChange={mockOnChange} data-testid="input-test" />);
      expect(input.value).toBe('abc');
    });

    test('should render with (Optional) inside the placeholder when it does not have a label and it is not required', () => {
      render(<Input size="medium" required={false} data-testid="input-test" />);
      const input = screen.getByTestId('input-test');
      expect(input.placeholder).toBe('Placeholder text (Optional)');
    });

    test('should render (Optional) text when has a label and it is not required', () => {
      render(<Input label="Label" required={false} />);
      expect(screen.getByText('(Optional)')).toBeInTheDocument();
    });

    test('should render characterCounter when characterCounter and maxLength are settled', () => {
      render(<Input characterCounter maxLength={100} data-testid="input-test" />);
      expect(screen.getByText('0/100')).toBeInTheDocument();
      const input = screen.getByTestId('input-test');
      fireEvent.change(input, { target: { value: '123' } });
      expect(screen.getByText('3/100')).toBeInTheDocument();
    });
  });

  test('should render input with prefix', () => {
    render(<Input prefix="@" />);
    expect(screen.getByText('@')).toBeInTheDocument();
  });

  test('should render input with sufix', () => {
    render(<Input prefix="#" />);
    expect(screen.getByText('#')).toBeInTheDocument();
  });
});
